# filename: payment-switch/app/payment_metrics.py
"""
Records business-level payment metrics.
Call record_payment() after every payment attempt completes.
"""

import time
from contextlib import asynccontextmanager
from typing import Optional

from shared.metrics.registry import (
    PAYMENT_INITIATED_TOTAL,
    PAYMENT_AMOUNT_PAISE,
    PAYMENT_TOTAL_AMOUNT_PAISE,
    PAYMENT_E2E_LATENCY_SECONDS,
    PAYMENT_ERRORS_TOTAL,
)


def _bank_from_vpa(vpa: str) -> str:
    """Extract bank identifier from VPA handle suffix."""
    handle_map = {
        "sbi": "SBI", "oksbi": "SBI",
        "okicici": "ICICI", "icici": "ICICI",
        "okhdfcbank": "HDFC", "hdfc": "HDFC",
        "ybl": "YESBANK", "okaxis": "AXIS",
    }
    suffix = vpa.split("@")[-1].lower() if "@" in vpa else "unknown"
    return handle_map.get(suffix, suffix.upper())


def record_payment(
    payer_vpa:    str,
    payee_vpa:    str,
    amount_paise: int,
    status:       str,          # SUCCESS | FAILED
    idem_result:  str,          # NEW | CACHED
    error_kind:   Optional[str] = None,  # validation|routing|bank_error|timeout
    duration_s:   float = 0.0,
) -> None:
    payer_bank = _bank_from_vpa(payer_vpa)
    payee_bank = _bank_from_vpa(payee_vpa)

    PAYMENT_INITIATED_TOTAL.labels(
        payer_bank  = payer_bank,
        payee_bank  = payee_bank,
        status      = status,
        idem_result = idem_result,
    ).inc()

    PAYMENT_AMOUNT_PAISE.labels(
        payer_bank = payer_bank,
        payee_bank = payee_bank,
        status     = status,
    ).observe(amount_paise)

    if status == "SUCCESS":
        PAYMENT_TOTAL_AMOUNT_PAISE.labels(
            payer_bank = payer_bank,
            payee_bank = payee_bank,
        ).inc(amount_paise)

    if duration_s > 0:
        PAYMENT_E2E_LATENCY_SECONDS.labels(
            payee_bank = payee_bank,
            status     = status,
        ).observe(duration_s)

    if error_kind:
        PAYMENT_ERRORS_TOTAL.labels(
            payee_bank = payee_bank,
            error_kind = error_kind,
        ).inc()


@asynccontextmanager
async def payment_timer(payer_vpa: str, payee_vpa: str,
                        amount_paise: int, idem_result: str):
    """
    Async context manager that times the payment block and records
    the result automatically.

    Usage:
        async with payment_timer("alice@sbi","bob@sbi", 10000, "NEW") as ctx:
            result = await execute_payment(...)
            ctx.status     = result["status"]
            ctx.error_kind = None
    """
    class _Ctx:
        status     = "FAILED"
        error_kind = "unknown"

    ctx   = _Ctx()
    start = time.perf_counter()
    try:
        yield ctx
    except Exception:
        ctx.status     = "FAILED"
        ctx.error_kind = ctx.error_kind or "unknown"
        raise
    finally:
        record_payment(
            payer_vpa    = payer_vpa,
            payee_vpa    = payee_vpa,
            amount_paise = amount_paise,
            status       = ctx.status,
            idem_result  = idem_result,
            error_kind   = ctx.error_kind if ctx.status == "FAILED" else None,
            duration_s   = time.perf_counter() - start,
        )
